/// The project indicator, and the activity spinner beside it, on a
/// background darker than the tab bar's, the whole height of the row, with
/// no line between it and what follows.
fn render_indicator_area(&self, cx: &Context<Self>) -> impl IntoElement {
    let background = crate::theme::color(crate::theme::palette(cx).pressed);
    gpui_kit::TestSupportExt::test_support(
        h_flex()
            .id("ribbon-prefix")
            .h_full()
            .flex_none()
            .items_center()
            .px_1()
            .bg(background)
            .child(self.project_indicator.clone())
            .children(self.render_activity(cx)),
    )
}

