    #[gpui_kit::test]
    async fn ribbon_tabs_are_drawn_beside_the_project_indicator(cx: &mut TestAppContext) {
        use gpui_kit::component::{Theme, ThemeMode};
        cx.update(|cx| {
            gpui_kit::init(cx);
            crate::theme::init(cx);
            piton_syntax::init();
            ProjectDirectory::init(cx);
        });
